#!/usr/bin/env python3
"""Print the repository greeting from the source-of-truth file."""

from pathlib import Path


def main():
    path = Path(__file__).resolve().parent / "greeting.txt"
    text = path.read_text(encoding="utf-8")
    lines = text.splitlines()
    if len(lines) != 1:
        raise SystemExit("greeting must be exactly one line")
    print(lines[0])


if __name__ == "__main__":
    main()
